import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.14942469, -0.411950885, 0.18690865], 'basis': [[-0.0, 0.9279276207002078, -0.37276042003095117], [0.607492361780828, 0.29609311416083867, 0.7370765890492577], [0.7943255191531691, -0.22644910794301598, -0.5637089418608336]], 'axis': [-0.37276042003095117, 0.7370765890492577, -0.5637089418608336], 'zmin': -0.0410595402721344, 'zmax': 0.04414042620292201, 'profiles': [{'outer': [[-0.07078267600436833, 0.05557145620473277], [-0.06396607941835976, 0.056987754758707945], [-0.05980193772341555, 0.05773384196111899], [-0.05480559934704074, 0.057344332416239575], [-0.04925718271363584, 0.05682627803851107], [-0.0489647292828131, 0.05689138820418149], [-0.04826407784179483, 0.058257313163829504], [-0.04578130685996288, 0.06006216329453837], [-0.04293597794255539, 0.06113675266877433], [-0.03995064588566296, 0.061462371804716046], [-0.0366247022443337, 0.06084645112423967], [-0.03318062704724321, 0.05943391437008095], [-0.029382276343080837, 0.056940492523997355], [-0.028748188925087143, 0.05626950562315462], [-0.027068607573430502, 0.05569699962700415], [-0.009348769005921334, 0.03543956530410508], [0.000892596150079698, 0.025873361515120846], [0.004352709438313066, 0.025007851222098795], [0.0119660976171364, 0.023701999473488212], [0.023973678243363272, 0.02420885922259318], [0.03623673982261691, 0.023856713165187646], [0.04695639258181804, 0.020048920573111945], [0.05628366937297319, 0.018332606530596852], [0.05833474501326864, 0.018970809113182226], [0.06388088225058354, 0.020914796657436865], [0.07654269733602935, 0.027309766118106767], [0.07903918027888883, 0.027688260542583876], [0.08466674224016497, 0.02465516325689116], [0.08575697857418914, 0.02289057483754641], [0.0871714309757815, 0.02014830470609934], [0.08835512924231118, 0.016186034242837894], [0.08894288739408025, 0.012202455465731342], [0.08871218895287147, 0.008015231397212531], [0.08696509432209806, 0.004850995426363885], [0.083647386848144, 0.0015633068003754846], [0.07694295240086825, -0.0004095969139420818], [0.06703058708667389, -3.2317593825213797e-05], [0.059676796558723516, -0.005945303654015236], [0.05878682358879032, -0.007532929024207798], [0.05860995928984947, -0.00798802140821629], [0.05916771462155219, -0.00847897432415634], [0.06211592734262805, -0.008942128908745507], [0.06800379330758627, -0.009205882735720984], [0.07559490995249483, -0.01146660330856783], [0.07950598473239619, -0.01452881165001388], [0.0799427436735111, -0.019096239816412706], [0.07846783035483211, -0.02301899551421354], [0.07727003884446908, -0.024036283559872643], [0.075070117121928, -0.026418628672503077], [0.07436444497506407, -0.026504013447180168], [0.06901697798728414, -0.026092182522397804], [0.06355957729324484, -0.02344235508618625], [0.05879701313192605, -0.020774911296576503], [0.05650770088059129, -0.020245014861696574], [0.05608573481140618, -0.021411371429038213], [0.05566026926547717, -0.025174234298364878], [0.05804391217259654, -0.02676777229613487], [0.06020551658845372, -0.027945754653551504], [0.0665031026659432, -0.03180551425230821], [0.07231444430230134, -0.0357536226542998], [0.07590392217564387, -0.03977919029271466], [0.07574750754171228, -0.04188052834241859], [0.07631313215629433, -0.04497317852134626], [0.07435475542430574, -0.04786039922116584], [0.06970503412007656, -0.049056221272909366], [0.06482457474943029, -0.047479930395714104], [0.05967506881250905, -0.044294775282698776], [0.05386370044712837, -0.041088308878840886], [0.05187759640411383, -0.04006622900536265], [0.0475633983520458, -0.040205624010637375], [0.048809868806540514, -0.04268418285437041], [0.051204525526510836, -0.0443090555800064], [0.05437948406643235, -0.04847605139715431], [0.05360039638786722, -0.05294952058614988], [0.05365381318198895, -0.05347174171896108], [0.05334671337911387, -0.05365826167760998], [0.04986108097366271, -0.0567262273049484], [0.04954822936550425, -0.056860321318887116], [0.04463994674894775, -0.05629158760374805], [0.04416782182374798, -0.05602915513731433], [0.04047697087978772, -0.052116646702838894], [0.03765931372575829, -0.05015839764780775], [0.03567561217654744, -0.053505337942780035], [0.03662229268168345, -0.05482861928821926], [0.037274286289840024, -0.05551769725437873], [0.03949074538102277, -0.05935751258581592], [0.03706841288491458, -0.06289671351782057], [0.03434083656571845, -0.06498532106141357], [0.03014435886933699, -0.06605521016912526], [0.026260572114444977, -0.0628290177690685], [0.017741473484459112, -0.0609514183834732], [0.005151536111561778, -0.06282939695402474], [-0.009816781154720252, -0.05759222438323005], [-0.022236285874191963, -0.04406983560602753], [-0.03231595573191259, -0.03094990945014607], [-0.044523911446982076, -0.01990898568384734], [-0.0590225862307459, -0.011641043575261752], [-0.0726917975989182, -0.0011275958267704805], [-0.0846359238660201, 0.013178875932596786], [-0.08916491033998902, 0.026753177782681412], [-0.0880471694382973, 0.03761425878051015], [-0.08421043696771642, 0.044541791560735226], [-0.07628650370948989, 0.0523107682656614]], 'holes': []}], 'simplify_tolerance': 3.5621559546813855e-05, 'sketch_entity_count': 124}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
